#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp> // pour boost::algorithm::replace_all()

std::string convertMarkdownToHtml(std::string& markdown) {
    // Remplacement des balises Markdown par leurs équivalents HTML
    boost::algorithm::replace_all(markdown, "\\n", "\n");
    boost::algorithm::replace_all(markdown, "\\t", "\t");
    boost::algorithm::replace_all(markdown, "\n\n", "<br><br>");
    boost::algorithm::replace_all(markdown, "\n", "<br>");
    boost::algorithm::replace_all(markdown, "**", "<strong>");
    boost::algorithm::replace_all(markdown, "__", "<strong>");
    boost::algorithm::replace_all(markdown, "*", "<em>");
    boost::algorithm::replace_all(markdown, "_", "<em>");
