6. Création du serpent: Ajoutez les structures et fonctions suivantes pour créer et manipuler le serpent:

```c
typedef struct {
    int x, y;
    SDL_Texture *texture;
} SnakePart;

typedef struct {
    int x, y;
    int width, height;
    SDL_Texture *texture;
} Food;

typedef struct {
    SnakePart *parts;
    int numParts;
    int direction;
    int score;
} Snake;

Snake *createSnake(int x, int y, int width, int height) {
    Snake *snake = malloc(sizeof(Snake));
    snake->parts = malloc(sizeof(SnakePart));
    snake->parts[0].x = x;
    snake->parts[0].y = y;
    snake->parts[0].texture = NULL;
    snake->numParts = 1;
    snake->direction = SDL_SCANCODE_LEFT;
    snake->score = 0;

    return snake;
}

void addSnakePart(Snake *snake) {
    SnakePart *newPart = malloc(sizeof(SnakePart));
    newPart->x = snake->parts[snake->numParts - 1].x;
    newPart->y = snake->parts[snake->numParts - 1].y;
    newPart->texture = NULL;

    snake->parts = realloc(snake->parts, sizeof(SnakePart) * (snake->numParts + 1));
    snake->parts[snake->numParts] = *newPart;
    snake->numParts++;
}

void moveSnake(Snake *snake, int screenWidth, int screenHeight) {
    for (int I = snake->numParts - 1; I > 0; i--) {
        snake->parts[i].x = snake->parts[i - 1].x;
        snake->parts[i].y = snake->parts[i - 1].y;
    }

    switch (snake->direction) {
        case SDL_SCANCODE_UP:
            snake->parts[0].y -= 20;
            break;
        case SDL_SCANCODE_DOWN:
            snake->parts[0].y += 20;
            break;
        case SDL_SCANCODE_LEFT:
            snake->parts[0].x -= 20;
            break;
        case SDL_SCANCODE_RIGHT:
            snake->parts[0].x += 20;
            break;
    }

    if (snake->parts[0].x < 0) {
        snake->parts[0].x = screenWidth - 20;
    } else if (snake->parts[0].x > screenWidth - 20) {
        snake->parts[0].x = 0;
    }

    if (snake->parts[0].y < 0) {
        snake->parts[0].y = screenHeight - 20;
    } else if (snake->parts[0].y > screenHeight - 20) {
        snake->parts[0].y = 0;
    }
}

bool snakeEatsFood(Snake *snake, Food *food) {
    return snake->parts[0].x == food->x && snake->parts[0].y == food->y;
}

void eatFood(Snake *snake, Food *food) {
    addSnakePart(snake);
    snake->score++;
    food->x = rand() % (screenWidth / 20) * 20;
    food->y = rand() % (screenHeight / 20) * 20;
}
```

