```c
void drawScene(Snake *snake, Food *food, TTF_Font *font) {
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
    SDL_RenderClear(renderer);

    for (int I = 0; I < snake->numParts; i++) {
        SDL_Rect srcRect = { 0, 0, 20, 20 };
        SDL_Rect destRect = { snake->parts[i].x, snake->parts[i].y, 20, 20 };
        SDL_RenderCopy(renderer, snake->parts[i].texture, &srcRect, &destRect);
    }

    SDL_Rect foodRect = { food->x, food->y, food->width, food->height };
    SDL_RenderCopy(renderer, food->texture, NULL, &foodRect);

    SDL_Color textColor = { 255, 255, 255 };
    char scoreText[64];
    sprintf(scoreText, "Score: %d", snake->score);
    SDL_Texture *scoreTexture = loadTextTexture(renderer, scoreText, font, textColor);
    SDL_Rect scoreRect = { 10, 10, 0, 0 };
    SDL_QueryTexture(scoreTexture, NULL, NULL, &scoreRect.w, &scoreRect.h);
    scoreRect.x = screenWidth - scoreRect.w - 10;
    SDL_RenderCopy(renderer, scoreTexture, NULL, &scoreRect);

    SDL_RenderPresent(renderer);
}
```

9. Boucle principale: Ajoutez la boucle principale pour exécuter le jeu:

```c
int runGame(Snake *snake, Food *food, TTF_Font *font) {
    while (true) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            switch (event.type) {
                case SDL_QUIT:
                    return 0;
                case SDL_KEYDOWN:
                    if (event.key.repeat == 0) {
                        switch (event.key.keysym.sym) {
                            case SDL_SCANCODE_UP:
                            case SDL_SCANCODE_DOWN:
                            case SDL_SCANCODE_LEFT:
                            case SDL_SCANCODE_RIGHT:
                                snake->direction = event.key.keysym.sym;
                                break;
                        }
                    }
                    break;
            }
        }

        moveSnake(snake, screenWidth, screenHeight);

        if (snakeEatsFood(snake, food)) {
            eatFood(snake, food);
        }

        drawScene(snake, food, font);
    }

    return 1;
}
```

